/**
 * Check if a given object implements the InlineObject3 interface.
 */
export function instanceOfInlineObject3(value) {
    return true;
}
export function InlineObject3FromJSON(json) {
    return InlineObject3FromJSONTyped(json, false);
}
export function InlineObject3FromJSONTyped(json, ignoreDiscriminator) {
    if (json == null) {
        return json;
    }
    return {
        performanceRating: json["performance_rating"] == null
            ? undefined
            : json["performance_rating"],
        returnRating: json["return_rating"] == null ? undefined : json["return_rating"],
        riskRating: json["risk_rating"] == null ? undefined : json["risk_rating"],
    };
}
export function InlineObject3ToJSON(json) {
    return InlineObject3ToJSONTyped(json, false);
}
export function InlineObject3ToJSONTyped(value, ignoreDiscriminator = false) {
    if (value == null) {
        return value;
    }
    return {
        performance_rating: value["performanceRating"],
        return_rating: value["returnRating"],
        risk_rating: value["riskRating"],
    };
}
